import org.javatuples.Pair;

public class GameCharacter {
    private String name;
    private int healthPoints;
    private boolean isDreaming;
    private boolean isInComa;
    private boolean isAngry;
    private boolean isCalm;

    public GameCharacter(String name) {
        this.name = name;
        this.healthPoints = 100; // Initial health points
        this.isDreaming = true;
        this.isInComa = false;
        this.isAngry = false;
        this.isCalm = true;
    }

    public void updateHealth(int damage) {
        healthPoints -= damage;
        System.out.println("Health: " + healthPoints);
    }

    public void setDreaming(boolean dreaming) {
        isDreaming = dreaming;
    }

    public void setInComa(boolean inComa) {
        isInComa = inComa;
    }

    public void setAngry(boolean angry) {
        isAngry = angry;
    }

    public void setCalm(boolean calm) {
        isCalm = calm;
    }

    public void printDetails() {
        System.out.println("Name: " + name);
        System.out.println("Health Points: " + healthPoints);
        System.out.println("Dreaming: " + (isDreaming ? "Yes" : "No"));
        System.out.println("In Coma: " + (isInComa ? "Yes" : "No"));
        System.out.println("Angry: " + (isAngry ? "Yes" : "No"));
        System.out.println("Calm: " + (isCalm ? "Yes" : "No"));
    }
}

public class Main {
    public static void main(String[] args) {
        GameCharacter player = new GameCharacter("Booleean");

        // Update health after taking damage
        player.updateHealth(20); // Player takes 20 damage

        // Set various attributes based on conditions
        player.setDreaming(true);
        player.setInComa(false);
        player.setAngry(true);
        player.setCalm(false);

        // Print details of the player
        player.printDetails();
    }
}
